import React, { useState } from 'react';
import axios from 'axios';

function ResumeForm({ setResumeData }) {
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    summary: '',
    experience: '',
    education: '',
    skills: '',
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleAIEnhance = async () => {
    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/ai-resume', form);
      setResumeData(res.data);
    } catch (err) {
      alert('AI enhancement failed.');
    }
    setLoading(false);
  };

  return (
    <div className="resume-form">
      <h2>Enter Your Details</h2>
      <input name="name" placeholder="Full Name" value={form.name} onChange={handleChange} />
      <input name="email" placeholder="Email" value={form.email} onChange={handleChange} />
      <input name="phone" placeholder="Phone" value={form.phone} onChange={handleChange} />
      <textarea name="summary" placeholder="Professional Summary" value={form.summary} onChange={handleChange} />
      <textarea name="experience" placeholder="Work Experience" value={form.experience} onChange={handleChange} />
      <textarea name="education" placeholder="Education" value={form.education} onChange={handleChange} />
      <textarea name="skills" placeholder="Skills (comma separated)" value={form.skills} onChange={handleChange} />
      <button onClick={handleAIEnhance} disabled={loading}>{loading ? 'Enhancing...' : 'Enhance with AI'}</button>
    </div>
  );
}

export default ResumeForm;
